"""KIM parsing and PDF checks, on PDFs generated by the tests."""

from datetime import date

import pymupdf
from fixture_builders import kim_pdf, sid_pdf

from ingestion.parse_pdf import (
    dated_from,
    full_text,
    is_pdf,
    parse_kim,
    table_to_text,
    text_layer_chars,
)
from ingestion.sanity import check_pdf_text

SCHEME_NAME = "HDFC Mid Cap Fund – Direct Growth"


def _joined(sections) -> str:
    return "\n".join(f"{s.heading}\n{s.text}" for s in sections)


def test_minimum_amount_table_is_parsed_as_a_table():
    tables = [s for s in parse_kim(kim_pdf()) if s.is_table]
    assert len(tables) == 1
    table = tables[0]
    assert "Minimum Application Amount" in table.heading
    assert "Purchase (including switch-in): ₹100/- and any amount thereafter" in table.text
    assert "Redemption (including switch-out): ₹100 and in multiples of ₹1/- thereafter" in (
        table.text
    )
    assert table.page == 2


def test_suitability_table_and_performance_block_are_dropped():
    text = _joined(parse_kim(kim_pdf())).lower()
    for banned in ["suitable for", "riskometer", "since inception", "18.50%", "past performance"]:
        assert banned not in text, banned


def test_exit_load_after_the_performance_block_is_kept():
    text = _joined(parse_kim(kim_pdf()))
    assert "Exit Load" in text and "1.00%" in text


def test_kim_and_sid_pass_their_checks():
    assert check_pdf_text(_joined(parse_kim(kim_pdf())), "KIM", SCHEME_NAME) == []
    assert check_pdf_text(full_text(sid_pdf()), "SID", SCHEME_NAME) == []


def test_pdf_checks_catch_problems():
    assert check_pdf_text("too short", "KIM", SCHEME_NAME)
    sid_text = full_text(sid_pdf())
    assert any("not found" in p for p in check_pdf_text(sid_text, "SID", "HDFC Small Cap Fund"))
    assert any("Minimum Application" in p for p in check_pdf_text(sid_text, "KIM", SCHEME_NAME))


def test_scanned_pdf_has_no_text_layer():
    doc = pymupdf.open()
    page = doc.new_page()
    page.draw_rect(pymupdf.Rect(50, 50, 300, 300), fill=(0.5, 0.5, 0.5))
    scanned = doc.tobytes()
    assert text_layer_chars(scanned) == 0
    assert text_layer_chars(kim_pdf()) > 300


def test_is_pdf():
    assert is_pdf(kim_pdf())
    assert not is_pdf(b"<html>not a pdf</html>")


def test_dated_from_link_title_or_url():
    url = "https://files.hdfcfund.com/KIM%20-%20HDFC%20Mid%20Cap%20Fund%20dated%20November%2021%2C%202025.pdf"
    assert dated_from("KIM - HDFC Mid Cap Fund", url) == date(2025, 11, 21)
    assert dated_from("Fund Facts - HDFC Mid Cap Fund", "https://x/fund-facts.pdf") is None


def test_table_to_text_with_and_without_a_header():
    with_header = [["Purchase", "Redemption"], ["Rs.100", "Rs.100"]]
    assert table_to_text(with_header) == "Purchase: Rs.100; Redemption: Rs.100."
    without_header = [["Equity", "", "65"], ["Debt", "0", "35"]]
    assert table_to_text(without_header) == "Equity | 65\nDebt | 0 | 35"
